c.python:
class Solution:
    def maxSubstrings(self, s: str) -> int:
        used = set()
        count = 0
        for c in s:
            if c not in used:
                used.add(c)
                count += 1
        return count

c.cpp:
class Solution {
public:
    int maxSubstrings(string s) {
        bool used[26] = {};
        int count = 0;
        for (char c : s)
            if (!used[c - 'a']) { used[c - 'a'] = true; count++; }
        return count;
    }
};

